CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260928083843_InitialCreate') THEN
    CREATE TABLE "Books" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Title" text,
        "ImageUrl" text,
        "Language" text,
        "Rating" integer NOT NULL,
        "Summary" text,
        "Author" text,
        "ReleaseYear" integer,
        CONSTRAINT "PK_Books" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260928083843_InitialCreate') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260928083843_InitialCreate', '10.0.12');
    END IF;
END $EF$;
COMMIT;

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260928150836_ValidationAndNewFieldsInBook') THEN
    ALTER TABLE "Books" ALTER COLUMN "Title" TYPE character varying(128);
    UPDATE "Books" SET "Title" = '' WHERE "Title" IS NULL;
    ALTER TABLE "Books" ALTER COLUMN "Title" SET NOT NULL;
    ALTER TABLE "Books" ALTER COLUMN "Title" SET DEFAULT '';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260928150836_ValidationAndNewFieldsInBook') THEN
    ALTER TABLE "Books" ALTER COLUMN "Language" TYPE character varying(32);
    UPDATE "Books" SET "Language" = '' WHERE "Language" IS NULL;
    ALTER TABLE "Books" ALTER COLUMN "Language" SET NOT NULL;
    ALTER TABLE "Books" ALTER COLUMN "Language" SET DEFAULT '';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260928150836_ValidationAndNewFieldsInBook') THEN
    ALTER TABLE "Books" ALTER COLUMN "ImageUrl" TYPE character varying(256);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260928150836_ValidationAndNewFieldsInBook') THEN
    ALTER TABLE "Books" ALTER COLUMN "Author" TYPE character varying(64);
    UPDATE "Books" SET "Author" = '' WHERE "Author" IS NULL;
    ALTER TABLE "Books" ALTER COLUMN "Author" SET NOT NULL;
    ALTER TABLE "Books" ALTER COLUMN "Author" SET DEFAULT '';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260928150836_ValidationAndNewFieldsInBook') THEN
    ALTER TABLE "Books" ADD "Genre" character varying(32);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260928150836_ValidationAndNewFieldsInBook') THEN
    ALTER TABLE "Books" ADD "InProcess" boolean NOT NULL DEFAULT FALSE;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260928150836_ValidationAndNewFieldsInBook') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260928150836_ValidationAndNewFieldsInBook', '10.0.12');
    END IF;
END $EF$;
COMMIT;

